}
.cli-tab:focus-visible {
  outline: 2px solid var(--vp-c-brand-1);
  outline-offset: 1px;
}
pre {
  margin: 0;
  min-height: 33rem;
  padding: 1.1rem 1.3rem 1.3rem;
  font-family: var(--vp-font-family-mono);
  font-size: 0.8rem;
  line-height: 1.6;
  color: #d7dee7;
  background: transparent;
  white-space: normal;
