  overflow-wrap: anywhere;
  padding-left: var(--hang);
  text-indent: calc(-1 * var(--hang));
}
pre :deep(b) {
  color: #f3f6fa;
  font-weight: 700;
}
pre :deep(.t-dim) {
  color: #7c8a9b;
}
pre :deep(.t-crit) {
  color: #ff6b6b;
  font-weight: 700;
}
pre :deep(.t-high) {
  color: #ff9a6b;
}
pre :deep(.t-med) {
  color: #f2c94c;
}
pre :deep(.t-ok) {
  color: #4fd18b;
}
pre :deep(.nw) {
  white-space: nowrap;
}
/* A phone is narrower than any terminal: keep the lines whole and let the sample scroll
   sideways inside its window (never the page), as it would in a terminal that small. */
@media (max-width: 640px) {
  pre {
    min-height: 26rem;
    padding: 0.9rem 1rem 1rem;
    font-size: 0.66rem;
    overflow-x: auto;
  }
  pre :deep(.ln) {
    white-space: pre;
    padding-left: 0;
    text-indent: 0;
  }
  .dots {
    display: none;
  }
  .cli-tabs {
    margin-left: 0;
    mask-image: linear-gradient(to right, #000 85%, transparent);
  }
}
